parts.text:
{
  "tom_tat": "Mô hình dự đoán mẫu này thuộc lớp DDoS với mức xác suất rất cao, trong khi lớp đứng thứ hai là DoS có khoảng cách chênh lệch cực lớn. Đặc trưng IAT đóng vai trò hỗ trợ mạnh mẽ nhất, đẩy giá trị đầu ra tăng lên đáng kể so với nền tham chiếu.",
  "lop_du_doan": "DDoS",
  "so_sanh_hai_lop": {
    "lop_thu_hai": "DoS",
    "khoang_cach_nho": false,
    "dien_giai": "Lớp đứng thứ hai là DoS có xác suất vô cùng nhỏ so với lớp DDoS. Cờ khoảng cách nhỏ đang tắt, cho thấy sự chênh lệch lớn giữa hai đầu ra nhưng điều này không được coi là bảo đảm tuyệt đối về nhãn thật."
  },
  "tong_hop_shap": {
    "ho_tro_manh_nhat": "IAT",
    "phan_doi_manh_nhat": null,
    "dien_giai": "Trong nhóm năm đặc trưng hàng đầu, tất cả đều tác động theo chiều hướng tăng và không có yếu tố nào mang giá trị âm trong phạm vi này."
  },
  "giai_thich_dac_trung": [
    {
      "ten_dac_trung": "IAT",
      "huong_tac_dong": "tang",
      "dien_giai": "Đây là yếu tố hỗ trợ nổi bật nhất trong top năm, đóng góp mức tăng lớn nhất vào đầu ra của lớp."
    },
    {
      "ten_dac_trung": "Protocol Type",
      "huong_tac_dong": "tang",
      "dien_giai": "Tác động này cùng chiều nhưng nhỏ hơn yếu tố dẫn đầu, đóng vai trò hỗ trợ bổ sung cho mô hình."
    },
    {
      "ten_dac_trung": "Magnitue",
      "huong_tac_dong": "tang",
      "dien_giai": "Đặc trưng này tiếp tục thúc đẩy kết quả dự đoán tăng lên với một mức đóng góp dương đáng chú ý."
    },
    {
      "ten_dac_trung": "Tot size",
      "huong_tac_dong": "tang",
      "dien_giai": "Sự hiện diện của đặc trưng này tạo thêm một khoảng tăng nhỏ giúp củng cố đầu ra của lớp."
    },
    {
      "ten_dac_trung": "Min",
      "huong_tac_dong": "tang",
      "dien_giai": "Đây là yếu tố có tác động nhỏ hơn trong nhóm năm đặc trưng, góp phần đẩy giá trị đầu ra dịch chuyển tăng."
    }
  ],
  "de_xuat_kiem_tra": [
    {
      "nguon_du_lieu": "Nhật ký lưu lượng mạng",
      "noi_dung_can_kiem_tra": "Kiểm tra sự đồng thời của nhiều nguồn đến cùng dịch vụ nếu có địa chỉ và thời gian.",
      "muc_dich": "Đối chiếu xem lưu lượng thực tế có dấu hiệu phân tán từ nhiều nguồn hướng về mục tiêu hay không."
    },
    {
      "nguon_du_lieu": "Nhật ký tài nguyên dịch vụ",
      "noi_dung_can_kiem_tra": "Đối chiếu lưu lượng với tình trạng tài nguyên và khả năng phục vụ, không tự đặt ngưỡng.",
      "muc_dich": "Đánh giá mức độ ảnh hưởng của tải mạng đối với hệ thống dịch vụ dựa trên dữ liệu ghi nhận."
    }
  ],
  "gioi_han": [
    "Kết quả SHAP chỉ giải thích đầu ra của mô hình phân loại và không chứng minh được quan hệ nhân quả hay cuộc tấn công thực tế.",
    "Giá trị xác suất của mô hình chưa được kiểm chứng là đã hiệu chỉnh hoàn toàn.",
    "Phạm vi phân tích chỉ giới hạn trong top năm đặc trưng được cung cấp và chưa bao gồm toàn bộ mọi thành phần ngoài nhóm."
  ]
}

